  async function loadAudit(){if(state.demo){$('#audit-table').innerHTML=state.audit.map(item=>`<tr><td>${dateTime(item.created_at)}</td><td>${escapeHtml(String(item.actor_id||'sistema').slice(0,8))}</td><td>${escapeHtml(item.action)}</td><td>${escapeHtml(item.entity)}</td><td>${escapeHtml(String(item.entity_id||'').slice(0,8))}</td></tr>`).join('')||emptyRow(5,'Sin eventos registrados.');return}const {data,error}=await client.from('audit_logs').select('id,actor_id,action,entity,entity_id,created_at').order('created_at',{ascending:false}).limit(1000);if(error){$('#audit-table').innerHTML=emptyRow(5,'No se pudo consultar la bitácora.');return}state.audit=data||[];$('#audit-table').innerHTML=state.audit.map(item=>`<tr><td>${dateTime(item.created_at)}</td><td>${escapeHtml(String(item.actor_id||'sistema').slice(0,8))}</td><td>${escapeHtml(item.action)}</td><td>${escapeHtml(item.entity)}</td><td>${escapeHtml(String(item.entity_id||'').slice(0,8))}</td></tr>`).join('')||emptyRow(5,'Sin eventos registrados.')}
