  function renderStaffActivity(data){const members=data.members||[];const events=data.events||[];$('#staff-active-count').textContent=members.filter(member=>member.active_now).length;$('#staff-login-count').textContent=members.reduce((count,member)=>count+Number(member.logins_24h||0),0);$('#staff-action-count').textContent=members.reduce((count,member)=>count+Number(member.actions_24h||0),0);$('#staff-members-table').innerHTML=members.map(member=>`<tr><td>${escapeHtml(member.name||'Sin nombre')}</td><td>${escapeHtml(member.email||'')}</td><td><span class="status-pill ${member.active_now?'confirmed':'inactive'}">${member.active_now?'Activo ahora':'Sin actividad'}</span></td><td>${dateTime(member.last_seen_at)}</td><td>${Number(member.logins_24h||0)}</td><td>${Number(member.actions_24h||0)}</td></tr>`).join('')||emptyRow(6,'No hay personal activo registrado.');$('#staff-events-table').innerHTML=events.map(item=>`<tr><td>${dateTime(item.created_at)}</td><td>${escapeHtml(item.name||item.email||'Personal')}</td><td>${escapeHtml(item.action||'')}</td><td>${escapeHtml(item.section||'')}</td><td>${escapeHtml(String(item.record_id||'').slice(0,8)||'—')}</td></tr>`).join('')||emptyRow(5,'Sin eventos en las últimas 24 horas.')}
  async function loadMessages(){if(state.demo){renderMessages();return}const {data,error}=await client.from('contact_messages').select('id,sender_name,email,message,status,created_at').order('created_at',{ascending:false}).limit(500);if(error){$('#messages-table').innerHTML=emptyRow(5,'No se pudo consultar la bandeja.');return}state.messages=data||[];renderMessages()}
  function renderMessages(){const filter=$('#message-status-filter').value;const rows=state.messages.filter(item=>filter==='all'||item.status===filter);$('#messages-table').innerHTML=rows.map(item=>`<tr><td>${dateTime(item.created_at)}</td><td>${escapeHtml(item.sender_name)}</td><td>${escapeHtml(item.email)}</td><td>${escapeHtml(item.message)}</td><td><select data-message-status="${item.id}">${['new','in_progress','resolved'].map(status=>`<option value="${status}" ${item.status===status?'selected':''}>${status}</option>`).join('')}</select></td></tr>`).join('')||emptyRow(5,'No hay consultas con ese filtro.')}
