  const complaintStatus={new:'Nueva',in_progress:'En atención',answered:'Respondida'};
  function complaintDue(createdAt){const due=new Date(createdAt);let days=0;while(days<15){due.setDate(due.getDate()+1);if(due.getDay()!==0&&due.getDay()!==6)days++}return due}
  function dueMarkup(item){if(item.status==='answered')return `<span>${item.responded_at?dateTime(item.responded_at):'Respondida'}</span>`;const due=complaintDue(item.created_at);const left=(due-Date.now())/86400000;return `<span class="${left<0?'due-overdue':left<=3?'due-soon':''}">${new Intl.DateTimeFormat('es-PE',{dateStyle:'short'}).format(due)}${left<0?' · vencida':''}</span>`}
  async function loadComplaints(){if(state.demo){renderComplaints();return}const {data,error}=await client.from('complaints').select('id,code,kind,consumer_name,document_type,document_number,address,phone,email,guardian_name,item_type,item_description,amount,order_reference,detail,consumer_request,status,provider_response,responded_at,created_at').order('created_at',{ascending:false}).limit(500);if(error){$('#complaints-table').innerHTML=emptyRow(8,'No se pudo consultar el Libro de Reclamaciones. Ejecuta el database/schema.sql actualizado.');return}state.complaints=data||[];renderComplaints()}
  function renderComplaints(){const filter=$('#complaint-status-filter').value;const rows=state.complaints.filter(item=>filter==='all'||(filter==='open'?item.status!=='answered':item.status===filter));$('#complaints-table').innerHTML=rows.map(item=>`<tr><td>${escapeHtml(item.code)}</td><td>${dateTime(item.created_at)}</td><td>${escapeHtml(item.consumer_name)}<br>${escapeHtml(item.email)}</td><td>${item.kind==='queja'?'Queja':'Reclamo'}</td><td class="complaint-snippet">${escapeHtml(String(item.detail).slice(0,120))}${String(item.detail).length>120?'…':''}</td><td>${dueMarkup(item)}</td><td><span class="status-pill ${item.status==='answered'?'confirmed':item.status==='new'?'pending':''}">${complaintStatus[item.status]||escapeHtml(item.status)}</span></td><td><button class="row-action" data-open-complaint="${escapeHtml(item.id)}">Atender</button></td></tr>`).join('')||emptyRow(8,'No hay hojas con ese filtro.')}
  function openComplaint(id){const item=state.complaints.find(complaint=>complaint.id===id);if(!item)return;const form=$('#complaint-form');form.reset();message($('#complaint-message'),'');form.elements.complaint_id.value=item.id;form.elements.status.value=item.status;form.elements.provider_response.value=item.provider_response||'';$('#complaint-title').textContent=`${item.kind==='queja'?'Queja':'Reclamo'} ${item.code}`;const details=[['Registrada',dateTime(item.created_at)],['Vence',new Intl.DateTimeFormat('es-PE',{dateStyle:'long'}).format(complaintDue(item.created_at))],['Consumidor',item.consumer_name],['Documento',`${item.document_type} ${item.document_number}`],['Domicilio',item.address],['Correo',item.email],['Teléfono',item.phone],['Apoderado',item.guardian_name],['Bien',`${item.item_type==='servicio'?'Servicio':'Producto'}: ${item.item_description}`],['Monto',item.amount!=null&&item.amount!==''?money(item.amount):''],['Pedido',item.order_reference],['Detalle',item.detail],['Pedido del consumidor',item.consumer_request]].filter(([,value])=>value);$('#complaint-details').innerHTML=details.map(([term,value])=>`<dt>${escapeHtml(term)}</dt><dd>${escapeHtml(value)}</dd>`).join('');$('#complaint-mailto').href=`mailto:${encodeURIComponent(item.email)}?subject=${encodeURIComponent(`Respuesta a su ${item.kind} ${item.code} · MSJ Fashion Store`)}&body=${encodeURIComponent(`Estimado/a ${item.consumer_name}:\n\nEn atención a su ${item.kind} ${item.code}, registrado el ${dateTime(item.created_at)}, le informamos lo siguiente:\n\n${item.provider_response||''}\n\nAtentamente,\nMSJ Fashion Store`)}`;$('#complaint-editor').showModal()}
  async function saveComplaint(event){event.preventDefault();const form=event.currentTarget;const values=new FormData(form);const id=String(values.get('complaint_id'));const status=String(values.get('status'));const response=String(values.get('provider_response')||'').trim();if(status==='answered'&&!response){message($('#complaint-message'),'Escribe la respuesta antes de marcarla como respondida.',true);return}const item=state.complaints.find(complaint=>complaint.id===id);const changes={status,provider_response:response,responded_at:status==='answered'?(item?.responded_at||new Date().toISOString()):null};const button=form.querySelector('button[type="submit"]');button.disabled=true;if(state.demo){if(item)Object.assign(item,changes);button.disabled=false;$('#complaint-editor').close();renderComplaints();return}const {error}=await client.from('complaints').update(changes).eq('id',id);button.disabled=false;if(error){message($('#complaint-message'),`No se pudo guardar: ${error.message}`,true);return}$('#complaint-editor').close();await loadComplaints()}
  // Carga o actualiza el catálogo de catalog-data.js: categorías, marcas, colecciones, productos, variantes y enlaces.
  function seedStock(text){let hash=0;for(const character of text)hash=(hash*31+character.charCodeAt(0))|0;return 2+Math.abs(hash)%23}
  function chunks(list,size){const parts=[];for(let index=0;index<list.length;index+=size)parts.push(list.slice(index,index+size));return parts}
  async function importMsjCatalog(){const catalog=window.MSJ_DATA;const status=$('#product-import-message');if(!catalog){message(status,'No se encontró catalog-data.js.',true);return}if(!confirm(`Se cargarán o actualizarán ${catalog.products.length} productos, ${catalog.categories.length} categorías, ${catalog.brands.length} marcas y ${catalog.collections.length} colecciones. El stock existente se conserva. ¿Continuar?`))return;const button=$('#import-msj-catalog');button.disabled=true;const step=text=>message(status,text);try{if(state.demo){step(`Vista previa: en Supabase se cargarían ${catalog.products.length} productos. Nada se guardó.`);return}step('1/6 Categorías…');const {data:categories,error:categoryError}=await client.from('categories').upsert(catalog.categories.map((category,index)=>({name:category.name,slug:category.slug,department:category.department,icon:category.icon,image_url:catalog.imageUrl(category.image,600),sort_order:index,is_active:true})),{onConflict:'slug'}).select('id,slug');if(categoryError)throw new Error(`Categorías: ${categoryError.message}. ¿Ejecutaste el database/schema.sql actualizado?`);const categoryIds=new Map(categories.map(row=>[row.slug,row.id]));step('2/6 Marcas…');const {data:brands,error:brandError}=await client.from('brands').upsert(catalog.brands.map(brand=>({name:brand.name,slug:brand.slug,is_active:true})),{onConflict:'slug'}).select('id,slug');if(brandError)throw new Error(`Marcas: ${brandError.message}`);const brandIds=new Map(brands.map(row=>[row.slug,row.id]));step('3/6 Colecciones…');const {data:collections,error:collectionError}=await client.from('collections').upsert(catalog.collections.map((collection,index)=>({name:collection.name,slug:collection.slug,description:collection.description,image_url:catalog.imageUrl(collection.image,900),sort_order:index,is_active:true})),{onConflict:'slug'}).select('id,slug');if(collectionError)throw new Error(`Colecciones: ${collectionError.message}`);const collectionIds=new Map(collections.map(row=>[row.slug,row.id]));step('4/6 Productos…');const productIds=new Map();for(const part of chunks(catalog.products,50)){const {data:rows,error}=await client.from('products').upsert(part.map(item=>({name:item.n,slug:item.s,sku:`MSJ-${item.s.toUpperCase()}`.slice(0,60),description:item.de||'',price:item.p,discount_percent:item.d||0,is_new:Boolean(item.nw),vip_only:Boolean(item.vip),audience:item.a,category_id:categoryIds.get(item.c),brand_id:brandIds.get(item.b)||null,image_url:catalog.imageUrl(item.i),model_image_url:catalog.imageUrl(item.m),is_active:true})),{onConflict:'slug'}).select('id,slug');if(error)throw new Error(`Productos: ${error.message}`);rows.forEach(row=>productIds.set(row.slug,row.id))}step('5/6 Tallas, colores y stock…');const ids=[...productIds.values()];const existing=[];for(const part of chunks(ids,100)){const {data:rows,error}=await client.from('product_variants').select('id,product_id,size,color,stock').in('product_id',part);if(error)throw new Error(`Variantes: ${error.message}`);existing.push(...rows)}const existingByKey=new Map(existing.map(variant=>[`${variant.product_id}|${variant.color}|${variant.size}`,variant]));const wanted=new Set();const variants=catalog.products.flatMap(item=>{const productId=productIds.get(item.s);return (item.co||['Único']).flatMap(color=>item.z.map(size=>{const key=`${productId}|${color}|${size}`;wanted.add(key);return {product_id:productId,size,color,stock:existingByKey.get(key)?.stock??seedStock(`${item.s}${color}${size}`),price:size==='100 ml'?Math.round(item.p*catalog.perfumeLargeFactor):null,is_active:true}}))});for(const part of chunks(variants,400)){const {error}=await client.from('product_variants').upsert(part,{onConflict:'product_id,size,color'});if(error)throw new Error(`Variantes: ${error.message}`)}const stale=existing.filter(variant=>!wanted.has(`${variant.product_id}|${variant.color}|${variant.size}`)).map(variant=>variant.id);for(const part of chunks(stale,200)){await client.from('product_variants').update({is_active:false}).in('id',part)}step('6/6 Colecciones de cada producto…');const links=catalog.products.flatMap(item=>(item.cl||[]).filter(slug=>collectionIds.has(slug)).map((slug,index)=>({collection_id:collectionIds.get(slug),product_id:productIds.get(item.s),sort_order:index})));for(const part of chunks(links,400)){const {error}=await client.from('collection_products').upsert(part,{onConflict:'collection_id,product_id',ignoreDuplicates:true});if(error)throw new Error(`Colecciones de productos: ${error.message}`)}for(const slug of ['mujer','hombre','unisex','accesorios']){const {data:category}=await client.from('categories').select('id').eq('slug',slug).maybeSingle();if(!category)continue;const {count}=await client.from('products').select('id',{count:'exact',head:true}).eq('category_id',category.id);if(!count)await client.from('categories').update({is_active:false}).eq('id',category.id)}step(`Listo: ${productIds.size} productos y ${variants.length} variantes cargados. Abre la tienda para verlos.`);await loadProducts();await loadDashboard()}catch(error){message(status,error.message||'No se pudo cargar el catálogo.',true)}finally{button.disabled=false}}

  // Genera un script SQL idempotente con el mismo catálogo, para ejecutarlo en el SQL Editor de Supabase.
  function catalogSql(){const catalog=window.MSJ_DATA;const q=value=>value===null||value===undefined?'null':typeof value==='number'?String(value):typeof value==='boolean'?String(value):`'${String(value).replace(/'/g,"''")}'`;const lines=[`-- Catálogo MSJ generado el ${new Date().toISOString()} desde catalog-data.js`,'-- Requiere database/schema.sql actualizado. Es idempotente: puedes ejecutarlo varias veces; conserva el stock existente.','begin;',`insert into public.categories (name,slug,department,icon,image_url,sort_order,is_active) values\n${catalog.categories.map((category,index)=>`  (${[category.name,category.slug,category.department,category.icon,catalog.imageUrl(category.image,600),index,true].map(q).join(',')})`).join(',\n')}\non conflict (slug) do update set name=excluded.name,department=excluded.department,icon=excluded.icon,image_url=excluded.image_url,sort_order=excluded.sort_order,is_active=true;`,`insert into public.brands (name,slug) values\n${catalog.brands.map(brand=>`  (${q(brand.name)},${q(brand.slug)})`).join(',\n')}\non conflict (slug) do update set name=excluded.name,is_active=true;`,`insert into public.collections (name,slug,description,image_url,sort_order) values\n${catalog.collections.map((collection,index)=>`  (${[collection.name,collection.slug,collection.description,catalog.imageUrl(collection.image,900),index].map(q).join(',')})`).join(',\n')}\non conflict (slug) do update set name=excluded.name,description=excluded.description,image_url=excluded.image_url,sort_order=excluded.sort_order,is_active=true;`,`insert into public.products (name,slug,sku,description,price,discount_percent,is_new,vip_only,audience,category_id,brand_id,image_url,model_image_url,is_active)\nselect v.name,v.slug,v.sku,v.description,v.price,v.discount,v.is_new,v.vip_only,v.audience,c.id,b.id,v.image_url,v.model_image_url,true from (values\n${catalog.products.map(item=>`  (${[item.n,item.s,`MSJ-${item.s.toUpperCase()}`.slice(0,60),item.de||'',item.p,item.d||0,Boolean(item.nw),Boolean(item.vip),item.a,item.c,item.b||null,catalog.imageUrl(item.i),catalog.imageUrl(item.m)].map(q).join(',')})`).join(',\n')}\n) as v(name,slug,sku,description,price,discount,is_new,vip_only,audience,category_slug,brand_slug,image_url,model_image_url)\njoin public.categories c on c.slug = v.category_slug left join public.brands b on b.slug = v.brand_slug\non conflict (slug) do update set name=excluded.name,description=excluded.description,price=excluded.price,discount_percent=excluded.discount_percent,is_new=excluded.is_new,vip_only=excluded.vip_only,audience=excluded.audience,category_id=excluded.category_id,brand_id=excluded.brand_id,image_url=excluded.image_url,model_image_url=excluded.model_image_url,is_active=true;`,`-- Desactiva variantes antiguas; las del catálogo se reactivan en la siguiente instrucción.\nupdate public.product_variants set is_active=false where product_id in (select id from public.products where slug in (${catalog.products.map(item=>q(item.s)).join(',')}));`,`insert into public.product_variants (product_id,size,color,stock,price,is_active)\nselect p.id,v.size,v.color,v.stock,v.price,true from (values\n${catalog.products.flatMap(item=>(item.co||['Único']).flatMap(color=>item.z.map(size=>`  (${[item.s,size,color,seedStock(`${item.s}${color}${size}`)].map(q).join(',')},${size==='100 ml'?Math.round(item.p*catalog.perfumeLargeFactor):'null::numeric'})`))).join(',\n')}\n) as v(slug,size,color,stock,price) join public.products p on p.slug = v.slug\non conflict (product_id,size,color) do update set price=excluded.price,is_active=true;`,`insert into public.collection_products (collection_id,product_id,sort_order)\nselect c.id,p.id,v.sort_order from (values\n${catalog.products.flatMap(item=>(item.cl||[]).map((slug,index)=>`  (${q(slug)},${q(item.s)},${index})`)).join(',\n')}\n) as v(collection_slug,product_slug,sort_order) join public.collections c on c.slug = v.collection_slug join public.products p on p.slug = v.product_slug\non conflict (collection_id,product_id) do nothing;`,'commit;'];return lines.join('\n\n')+'\n'}
  function downloadCatalogSql(){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([catalogSql()],{type:'text/plain;charset=utf-8'}));link.download='seed_catalog.sql';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);message($('#product-import-message'),`Se descargó seed_catalog.sql con ${window.MSJ_DATA.products.length} productos. Guárdalo en database/ y ejecútalo en el SQL Editor de Supabase.`)}

  // Reseñas
  const reviewStatus={pending:'En revisión',approved:'Aprobada',rejected:'Rechazada'};
  async function loadReviews(){if(state.demo){renderReviews();return}const {data,error}=await client.from('product_reviews').select('id,product_id,author_name,rating,comment,status,created_at,products(name)').order('created_at',{ascending:false}).limit(500);if(error){$('#reviews-table').innerHTML=emptyRow(7,'No se pudieron consultar las reseñas. Ejecuta el database/schema.sql actualizado.');return}state.reviews=data||[];renderReviews()}
  function renderReviews(){const filter=$('#review-status-filter').value;const rows=(state.reviews||[]).filter(item=>filter==='all'||item.status===filter);$('#reviews-table').innerHTML=rows.map(item=>`<tr><td>${dateTime(item.created_at)}</td><td>${escapeHtml(item.products?.name||'—')}</td><td>${escapeHtml(item.author_name||'Cliente')}</td><td>${'★'.repeat(item.rating)}${'☆'.repeat(5-item.rating)}</td><td class="complaint-snippet">${escapeHtml(item.comment)}</td><td><select data-review-status="${item.id}">${Object.entries(reviewStatus).map(([value,label])=>`<option value="${value}" ${item.status===value?'selected':''}>${label}</option>`).join('')}</select></td><td><button class="row-action danger-action" data-delete-review="${item.id}">Eliminar</button></td></tr>`).join('')||emptyRow(7,'No hay reseñas con ese filtro.')}
  async function updateReview(select){if(state.demo){const item=state.reviews.find(review=>review.id===select.dataset.reviewStatus);if(item)item.status=select.value;renderReviews();return}const {error}=await client.from('product_reviews').update({status:select.value}).eq('id',select.dataset.reviewStatus);if(error)alert(`No se pudo actualizar: ${error.message}`);await loadReviews()}
  async function deleteReview(button){if(!confirm('¿Eliminar esta reseña?'))return;if(state.demo){state.reviews=state.reviews.filter(review=>review.id!==button.dataset.deleteReview);renderReviews();return}const {error}=await client.from('product_reviews').delete().eq('id',button.dataset.deleteReview);if(error)alert(`No se pudo eliminar: ${error.message}`);await loadReviews()}

  // Cupones
  async function loadCoupons(){if(state.demo){renderCoupons();return}const {data,error}=await client.from('coupons').select('id,code,description,discount_type,discount_value,min_subtotal,starts_at,ends_at,max_uses,used_count,once_per_customer,is_active').order('created_at',{ascending:false});if(error){$('#coupons-table').innerHTML=emptyRow(7,'No se pudieron consultar los cupones. Ejecuta el database/schema.sql actualizado.');return}state.coupons=data||[];renderCoupons()}
  function renderCoupons(){$('#coupons-table').innerHTML=(state.coupons||[]).map(item=>`<tr><td><strong>${escapeHtml(item.code)}</strong><br><small>${escapeHtml(item.description)}</small></td><td>${item.discount_type==='percent'?`${Number(item.discount_value)}%`:money(item.discount_value)}</td><td>${money(item.min_subtotal)}</td><td>${item.ends_at?`Hasta ${new Intl.DateTimeFormat('es-PE',{dateStyle:'short'}).format(new Date(item.ends_at))}`:'Sin vencimiento'}</td><td>${item.used_count}${item.max_uses?` / ${item.max_uses}`:''}${item.once_per_customer?'<br><small>1 por cliente</small>':''}</td><td><span class="status-pill ${item.is_active?'confirmed':'inactive'}">${item.is_active?'Activo':'Inactivo'}</span></td><td><button class="row-action" data-toggle-coupon="${item.id}" data-active="${item.is_active}">${item.is_active?'Desactivar':'Activar'}</button></td></tr>`).join('')||emptyRow(7,'Todavía no hay cupones.')}
  async function saveCoupon(event){event.preventDefault();const form=event.currentTarget;const values=new FormData(form);const coupon={code:String(values.get('code')).trim().toUpperCase(),description:String(values.get('description')||'').trim(),discount_type:values.get('discount_type'),discount_value:Number(values.get('discount_value')),min_subtotal:Number(values.get('min_subtotal')||0),ends_at:values.get('ends_at')?new Date(`${values.get('ends_at')}T23:59:59-05:00`).toISOString():null,max_uses:values.get('max_uses')?Number(values.get('max_uses')):null,once_per_customer:values.get('once_per_customer')==='on',is_active:true};if(coupon.discount_type==='percent'&&coupon.discount_value>90){message($('#coupon-message'),'El porcentaje máximo es 90%.',true);return}if(state.demo){state.coupons=[{id:`demo-coupon-${Date.now()}`,used_count:0,...coupon},...(state.coupons||[])];$('#coupon-editor').close();renderCoupons();return}const {error}=await client.from('coupons').insert(coupon);if(error){message($('#coupon-message'),error.code==='23505'?'Ya existe un cupón con ese código.':`No se pudo crear: ${error.message}`,true);return}$('#coupon-editor').close();await loadCoupons()}
  async function toggleCoupon(button){const active=button.dataset.active==='true';if(state.demo){const item=state.coupons.find(coupon=>coupon.id===button.dataset.toggleCoupon);if(item)item.is_active=!active;renderCoupons();return}const {error}=await client.from('coupons').update({is_active:!active}).eq('id',button.dataset.toggleCoupon);if(error)alert(`No se pudo actualizar: ${error.message}`);await loadCoupons()}

  // Zonas de envío
  async function loadZones(){if(state.demo){renderZones();return}const {data,error}=await client.from('shipping_zones').select('id,name,description,cost,free_from,days_min,days_max,is_active').order('sort_order');if(error){$('#zones-table').innerHTML=emptyRow(7,'No se pudieron consultar las zonas. Ejecuta el database/schema.sql actualizado.');return}state.zones=data||[];renderZones()}
  function renderZones(){$('#zones-table').innerHTML=(state.zones||[]).map(zone=>`<tr data-zone-row="${zone.id}"><td><strong>${escapeHtml(zone.name)}</strong><br><small>${escapeHtml(zone.description)}</small></td><td><input class="zone-input" type="number" min="0" step="0.5" name="cost" value="${Number(zone.cost)}" aria-label="Costo ${escapeHtml(zone.name)}"></td><td><input class="zone-input" type="number" min="0" step="1" name="free_from" value="${zone.free_from??''}" placeholder="—" aria-label="Gratis desde ${escapeHtml(zone.name)}"></td><td><input class="zone-input" type="number" min="0" step="1" name="days_min" value="${zone.days_min}" aria-label="Días mínimos"></td><td><input class="zone-input" type="number" min="0" step="1" name="days_max" value="${zone.days_max}" aria-label="Días máximos"></td><td><input type="checkbox" name="is_active" ${zone.is_active?'checked':''} aria-label="Zona activa"></td><td><button class="row-action" data-save-zone="${zone.id}">Guardar</button></td></tr>`).join('')||emptyRow(7,'No hay zonas de envío.')}
  async function saveZone(button){const row=button.closest('tr');const value=name=>row.querySelector(`[name="${name}"]`);const changes={cost:Number(value('cost').value||0),free_from:value('free_from').value===''?null:Number(value('free_from').value),days_min:Number(value('days_min').value||0),days_max:Number(value('days_max').value||0),is_active:value('is_active').checked};if(changes.days_max<changes.days_min){alert('Los días máximos no pueden ser menores que los mínimos.');return}if(state.demo){Object.assign(state.zones.find(zone=>zone.id===button.dataset.saveZone)||{},changes);button.textContent='Guardado ✓';return}const {error}=await client.from('shipping_zones').update(changes).eq('id',button.dataset.saveZone);if(error){alert(`No se pudo guardar: ${error.message}`);return}button.textContent='Guardado ✓';setTimeout(()=>{button.textContent='Guardar'},1600)}

  // Boletín
  async function loadNewsletter(){if(state.demo){renderNewsletter();return}const {data,error}=await client.from('newsletter_subscribers').select('id,email,source,created_at').order('created_at',{ascending:false}).limit(2000);if(error){$('#newsletter-table').innerHTML=emptyRow(4,'No se pudo consultar el boletín. Ejecuta el database/schema.sql actualizado.');return}state.subscribers=data||[];renderNewsletter()}
  function renderNewsletter(){$('#newsletter-table').innerHTML=(state.subscribers||[]).map(item=>`<tr><td>${dateTime(item.created_at)}</td><td>${escapeHtml(item.email)}</td><td>${escapeHtml(item.source)}</td><td><button class="row-action danger-action" data-delete-subscriber="${item.id}">Dar de baja</button></td></tr>`).join('')||emptyRow(4,'Aún no hay suscriptores.')}
  async function deleteSubscriber(button){if(!confirm('¿Dar de baja este correo?'))return;if(state.demo){state.subscribers=state.subscribers.filter(item=>item.id!==button.dataset.deleteSubscriber);renderNewsletter();return}const {error}=await client.from('newsletter_subscribers').delete().eq('id',button.dataset.deleteSubscriber);if(error)alert(`No se pudo eliminar: ${error.message}`);await loadNewsletter()}

